INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter9-padmanayakas', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter9-padmanayakas-p1", "partName": "Fall of Warangal and Advent of Muslim Rule", "bodyMd": "In **1323 CE**, the Kakatiya capital fort of **Orugallu (Warangal)** fell before the Muslim army sent by the Delhi Sultanate. The campaign was led by **Ulugh Khan**, son of Ghiyasuddin Tughlaq (later known as **Muhammad bin Tughlaq**), under whose leadership the expansion continued further south. Their march advanced through Tamil Nadu without resistance until Madurai. The Andhra and Tamil regions conquered by the Muhammadans were merged together and made part of the **Ma''bar province** of the Delhi Sultanate. This marked the first time the Telugu land came under Muslim rule.\n\n**Excesses under early Muslim rule:**\n\n*   The victorious Muslim army committed widespread atrocities.\n*   Temples were destroyed and mosques built in their place.\n*   Ripened crops were forcibly seized from cultivators.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter9-padmanayakas-p2", "partName": "Musunuri Nayakas and the Revolt Against Muslim Rule", "bodyMd": "Faced with oppressive Muslim administration, the old royal houses, former Kakatiya armies, great chieftains (Mahasamanthas), and local dynastic families came together to resist. To lead the effort to liberate the collapsing Telugu land, they chose **Musunuri Prolaya Nayaka**, a warrior from the Vengi region, as their chief.\n\n*   In **1325**, the ancient republican political tradition of Andhra was revived — a significant development in the region''s political history.\n*   Under Prolaya Nayaka''s leadership, the Hindu kings of Andhra first organised a government-in-exile against Muslim rule, and subsequently established an independent kingdom. This is regarded as a golden chapter in Andhra history.\n*   Coastal Andhra came under Prolaya Nayaka''s control, while **Kapaya Nayaka**, his cousin, held Warangal at the time.\n*   Since Prolaya Nayaka had no children, on his death Kapaya Nayaka also became ruler of coastal Andhra.\n\n### Formation of the Recherla Padma Nayaka Kingdom\n\nAround the same period, the **Recherla dynasty**, belonging to the Velama community, established the Padma Nayaka kingdom in Telangana with its capital at **Rachakonda**. The rulers of **Devarakonda** were also Velamas. Both lines were originally Shaivites, and later became Vaishnavites.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter9-padmanayakas-p3", "partName": "The Six Kingdoms of the Deccan (1335–36)", "bodyMd": "By 1335–36, six major independent political powers had emerged in the Deccan, each rising from the confusion following the Kakatiya collapse:\n\n| # | Kingdom | Founder / Rulers |\n|---|---|---|\n| 1 | Coastal Andhra territories | Musunuri rulers |\n| 2 | Warangal | Kapaya Nayaka |\n| 3 | Reddy kingdom | Prolaya Vema Reddy |\n| 4 | Rachakonda and Devarakonda | Padma Nayakas |\n| 5 | Vijayanagara empire | Harihara and Bukkaraya |\n| 6 | Bahmani kingdom | A rebelling local governor of the Deccan |", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter9-padmanayakas-p4", "partName": "The Coalition of 77 Nayakas and Recovery of Warangal", "bodyMd": "Before launching their campaign against the Turks, **77 nayakas** united through a mutual agreement to fight together for their homeland. Their coming together under the leadership of Musunuri Prolaya Nayaka to re-establish Hindu rule is regarded as a great chapter in regional history.\n\n**Terms of the agreement among the 77 nayakas:**\n\n*   Muhammadan rule would be jointly driven out.\n*   Once achieved, each nayaka would take control of his own respective territory.\n*   No nayaka would interfere in the territory belonging to another — a term all of them accepted.\n\n**Sequence of events:**\n\n1.  Prolaya Nayaka shifted his capital from the Vengi region to **Rekapalli**, near Bhadrachalam on the banks of the Godavari.\n2.  Prolaya Nayaka died around **1330 CE**.\n3.  After his death, his cousin''s son, **Kapaya Nayaka**, took up the leadership.\n4.  In **1336**, Kapaya Nayaka attacked the Warangal fort, drove out the Muhammadans, and took control of it.\n5.  The capital was shifted from Rekapalli to Warangal.\n6.  Kapaya Nayaka assumed the titles **Andhra Suratrana**, **Andhra Deshadhishwara**, and **Kakatiya Sthapanacharya**.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter9-padmanayakas-p5", "partName": "Decline of Kapaya Nayaka''s Power", "bodyMd": "Kapaya Nayaka aspired to establish himself as the sovereign successor (chakravarti) of the Kakatiya empire, having made Warangal his own capital rather than sharing power under the earlier agreement. He steadily expanded his territory by strengthening his following.\n\n*   Recherla Singama Nayaka, who controlled a larger share of Telangana, grew envious of Kapaya Nayaka''s ambitions, and as a result encroached upon and seized some of his territories.\n    \n*   Constant warfare that followed steadily weakened Kapaya Nayaka''s strength.\n    \n*   Kapaya Nayaka died in **1367–68**.\n    \n*   Thereafter, **Anavota Reddy** gradually brought the forts of Telangana under his own control.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter9-padmanayakas-p6", "partName": "Padma Nayakas", "bodyMd": "### Origins and Rise\n\nThe Padma Nayakas were originally feudatories (samanthas) of the Kakatiya kings. Their rise began during the reign of **Ganapatideva**, when they took an enthusiastic part in politics and contributed to the expansion of the Kakatiya empire. Their native place was **Amanagallu**, in present-day Nalgonda district.\n\n### Capitals and Forts\n\nAfter becoming independent, the Padma Nayaka rulers first held Amanagallu, and later established their capitals at **Rachakonda** and **Devarakonda**, where they built strong forts. Rachakonda town is located in the Narayanapuram mandal of Nalgonda district.\n\n**Rachakonda and the protection of dharma:**\n\n*   For the kingdom to remain stable, the Padma Nayakas of Rachakonda committed themselves to the protection of dharma.\n*   After the fall of the Kakatiyas, Warangal and the surrounding Andhra regions had passed under Muslim control, and in these circumstances, protecting one''s own religion (swadharma), one''s own community (swamata), and promoting general development became essential duties of the rulers.\n*   All religious communities and sects had a place at Rachakonda.\n\n### Cultural and Literary Patronage\n\nRachakonda gained renown for its contributions to literature, music, and dramatic arts, and Sanskrit received great patronage under its rulers.\n\n*   **Court poet:** Salakya Ayyalarjudu, court poet of the Padma Nayakas, completed the **Bhaskara Ramayanam**.\n*   **Telugu poets patronised:** Gaurana and Pothana were the most celebrated Telugu poets who received the patronage of the Rachakonda rulers.\n\n### Sarvagna Singabhupaludu\n\n**Sarvagna Singabhupaludu**, a Rachakonda ruler, was himself a connoisseur of music and literature, a discerning aesthete, a prolific author, and the foremost among poets of his time. He extended his patronage to **Sreenatha**, who adorned the Rachakonda court.\n\n### State of Society and the Legacy of Pothana\n\nThe rulers of the age had grown degenerate, and ministers pursued selfish interests. Corrupted by the times, the people themselves turned to bribery. Continued contact and conflict with Muslim rulers steadily weakened Hindu society, which lacked genuine spiritual or selfless direction for the nation''s welfare.\n\nAgainst this backdrop, **Sri Rama** was upheld as the ideal ruler and **Ramarajyam** as the ideal state, a message spread to the world through the **Bhagavatam**. In Pothana''s hands, the Telugu language flourished; his writing flowed with natural sweetness, achieving a rare fulfilment of style and substance.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter9-padmanayakas-p7", "partName": "Decline and End of the Padma Nayaka Kingdom", "bodyMd": "After the fall of the Kakatiyas, the Musunuri and Recherla Padma Nayaka rulers governed Telangana for close to **150 years**. However, they were unable to provide capable and stable governance throughout this period, as their rule was spent almost entirely in continuous warfare — against the Bahmani Sultans, in hostility with the Delhi Sultans, and amid the rising influence of Vijayanagara and the Gajapatis, among other reasons. \n\nBy **1475 CE**, weakened by these prolonged conflicts, the Padma Nayaka kingdom came to an end. Even so, the Padma Nayakas played a major role in the history of Telangana.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter9-padmanayakas-p8", "partName": "Agriculture and Trade Under the Nayaka Period", "bodyMd": "The Kakatiyas had already developed Telangana as a region rich in irrigation tanks even before this period. Continuing this tradition, the Velama rulers too built tanks — **Anasomasamudram**, **Rayasamudram**, and **Nagasamudram** being chief among them — and promoted agriculture.\n\n*   Agricultural conditions remained generally satisfactory in parts of the region, though continuous military campaigns disrupted regular crop cultivation elsewhere.\n*   Trade and commerce received little protection during this turbulent period.\n*   Although kingdoms directed repeated military campaigns toward capturing the fertile Godavari coastal region, even when captured, they were unable to hold this territory for even ten days at a stretch.\n*   Foreign trade suffered as a result, but domestic trade continued — petty traders and cottage-industry workers carried on their livelihoods largely independent of the political turmoil.\n*   Agriculture remained the chief occupation, and even those engaged in other trades and crafts held lands of their own.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter9-padmanayakas-p9", "partName": "Recherla Padma Nayakas as Scholars", "bodyMd": "The Recherla Padma Nayakas were not merely patrons of literature but were themselves accomplished authors, composing several authoritative works in both Sanskrit and Telugu.\n\n**Sanskrit works:**\n\n*   Rasarnava Sudhakaram — a treatise on dramaturgy (Natyashastra)\n*   Ratnapanchalika — a Sanskrit drama\n*   Chamatkara Chandrika — a treatise on rhetoric (Alankarashastra)\n*   Amara Pada Parijatam — a commentary on the Amara Kosha\n*   Lakshanadeepika\n*   Harishchandropakhyanamu\n\n**Telugu works:**\n\n*   Simhasana Dvatrimshika\n*   Navanatha Charitra\n*   Bhagavatam\n*   Bhogini Dandakam\n\nThrough these contributions, literature came to occupy a distinguished place under the patronage of the Padma Nayakas.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter9-padmanayakas';
